mapper.select:
SELECT
ar.asset_report_id,
ar.report_month,
ar.total_asset_amount,
ar.total_asset_change_amount,
ar.monthly_saved_amount,
ar.goal_achievement_rate,
ar.created_at,
ar.updated_at
FROM asset_report ar
WHERE ar.child_id = #{childId}


    AND ar.report_month >= #{yearStart}
    AND ar.report_month < #{yearEndExclusive}



    AND (
    ar.report_month < #{cursorReportMonth}
    OR (
    ar.report_month = #{cursorReportMonth}
    AND ar.asset_report_id
    < #{cursorAssetReportId}
    )
    )


ORDER BY
ar.report_month DESC,
ar.asset_report_id DESC

LIMIT #{limit}

SELECT total_asset_amount
FROM asset_report
WHERE child_id = #{childId}
  AND report_month = #{reportMonth}
    LIMIT 1

SELECT monthly_saved_amount
FROM asset_report
WHERE child_id = #{childId}
  AND report_month = #{reportMonth}
    LIMIT 1
